// ==== Polvo de hadas + música ====
// SONRIE -> estallido de brillos en las mejillas.  Boca en "O" -> soplo desde la boca.
// La MÚSICA empieza con el primer gesto y sigue sonando (en bucle) hasta que reinicias.
// Siempre hay unos pocos brillos flotando alrededor.
// AJUSTES
var SONIDO = "assets/sonidos/fantasia.mp3";   // tu mp3 (si falta, suena el sonido sintetizado)
var VOLUMEN = 0.8;
var N = 90, COLORES = [0xffffff, 0xffe9a8, 0xd9b8ff, 0xb8e6ff];
var pool = [], idle = 0;

function makeTex() {
	var c = document.createElement("canvas"); c.width = c.height = 64; var g = c.getContext("2d");
	var r = g.createRadialGradient(32, 32, 0, 32, 32, 32); r.addColorStop(0, "rgba(255,255,255,1)"); r.addColorStop(0.25, "rgba(255,255,255,.55)"); r.addColorStop(1, "rgba(255,255,255,0)");
	g.fillStyle = r; g.fillRect(0, 0, 64, 64);
	g.fillStyle = "#fff"; g.beginPath(); g.moveTo(32, 2); g.quadraticCurveTo(34, 30, 62, 32); g.quadraticCurveTo(34, 34, 32, 62); g.quadraticCurveTo(30, 34, 2, 32); g.quadraticCurveTo(30, 30, 32, 2); g.fill();
	return new THREE.CanvasTexture(c);
}
function start() {
	var tex = makeTex();
	for (var i = 0; i < N; i++) {
		var s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }));
		s.visible = false; this.add(s); pool.push({ s: s, life: 0, max: 1, v: new THREE.Vector3(), size: 0.1 });
	}
}
function emit(x, y, z, vx, vy, vz, size, max) {
	for (var i = 0; i < pool.length; i++) if (pool[i].life <= 0) {
		var p = pool[i]; p.life = p.max = max * (0.7 + Math.random() * 0.6); p.size = size * (0.6 + Math.random() * 0.8);
		p.s.position.set(x, y, z); p.v.set(vx, vy, vz); p.s.material.color.setHex(COLORES[(Math.random() * COLORES.length) | 0]); p.s.visible = true; return;
	}
}
function burst(x, y, z, n) {
	for (var i = 0; i < n; i++) emit(x + (Math.random() - 0.5) * 0.2, y + (Math.random() - 0.5) * 0.2, z, (Math.random() - 0.5) * 0.7, Math.random() * 0.6, 0.1 + Math.random() * 0.3, 0.1, 1.6);
}
function sound() { if (window.folio) window.folio.sfx.music(SONIDO, VOLUMEN, "fantasia"); }   // no se reinicia si ya suena
function smileStart() { burst(-0.38, -0.2, 0.2, 14); burst(0.38, -0.2, 0.2, 14); burst(0, 0.1, 0.25, 8); sound(); }
function oMouth() {            // soplo: sale hacia delante desde la boca
	for (var i = 0; i < 26; i++) emit((Math.random() - 0.5) * 0.12, -0.43, 0.15, (Math.random() - 0.5) * 0.5, 0.1 + Math.random() * 0.3, 0.6 + Math.random() * 0.8, 0.09, 1.4);
	sound();
}
function update(event) {
	var d = event.delta / 1000;
	idle -= d; if (idle < 0) { idle = 0.18; emit((Math.random() - 0.5) * 1.2, -0.7 + Math.random() * 1.3, 0.1 + Math.random() * 0.2, 0, 0.05, 0, 0.05, 1.6); }
	for (var i = 0; i < pool.length; i++) {
		var p = pool[i]; if (p.life <= 0) continue;
		p.life -= d; if (p.life <= 0) { p.s.visible = false; continue; }
		p.v.y -= 0.35 * d; p.s.position.addScaledVector(p.v, d);
		var k = p.life / p.max; p.s.scale.setScalar(p.size * (0.4 + k)); p.s.material.opacity = Math.min(1, k * 2);
	}
}
